export function isPlainObject(value: unknown): boolean {
  if (value === null || typeof value !== "object") {
    return false;
  }
  const prototype = Object.getPrototypeOf(value);

  if (
    prototype !== null &&
    prototype !== Object.prototype &&
    Object.getPrototypeOf(prototype) !== null
  ) {
    return false;
  }

  if (Symbol.iterator in value) {
    return false;
  }

  if (Symbol.toStringTag in value) {
    return Object.prototype.toString.call(value) === "[object Module]";
  }

  return true;
}

import { isPlainObject } from "./_utils";
import type { Merger, DefuFn as DefuFunction, DefuInstance } from "./types";

// Base function to apply defaults
function _defu<T>(baseObject: T, defaults: any, namespace = ".", merger?: Merger): T {
  if (!isPlainObject(defaults)) {
    return _defu(baseObject, {}, namespace, merger);
  }

  const object = { ...defaults };

  for (const key of Object.keys(baseObject as Record<string, any>)) {
    if (key === "__proto__" || key === "constructor") {
      continue;
    }

    const value = (baseObject as Record<string, any>)[key];

    if (value === null || value === undefined) {
      continue;
    }

    if (merger && merger(object, key, value, namespace)) {
      continue;
    }

    if (Array.isArray(value) && Array.isArray(object[key])) {
      object[key] = [...value, ...object[key]];
    } else if (isPlainObject(value) && isPlainObject(object[key])) {
      object[key] = _defu(
        value,
        object[key],
        (namespace ? `${namespace}.` : "") + key.toString(),
        merger,
      );
    } else {
      object[key] = value;
    }
  }

  return object;
}

// Create defu wrapper with optional merger and multi arg support
export function createDefu(merger?: Merger): DefuFunction {
  return (...arguments_) =>
    // eslint-disable-next-line unicorn/no-array-reduce
    arguments_.reduce((p, c) => _defu(p, c, "", merger), {} as any);
}

// Standard version
export const defu = createDefu() as DefuInstance;
export default defu;

// Custom version with function merge support
export const defuFn = createDefu((object, key, currentValue) => {
  if (object[key] !== undefined && typeof currentValue === "function") {
    object[key] = currentValue(object[key]);
    return true;
  }
});

// Custom version with function merge support only for defined arrays
export const defuArrayFn = createDefu((object, key, currentValue) => {
  if (Array.isArray(object[key]) && typeof currentValue === "function") {
    object[key] = currentValue(object[key]);
    return true;
  }
});

export type { Defu, DefuFn, DefuInstance } from "./types";

export type Input = Record<string | number | symbol, any>;
export type IgnoredInput = boolean | number | null | any[] | Record<never, any> | undefined;

export type Merger = <T extends Input, K extends keyof T>(
  object: T,
  key: keyof T,
  value: T[K],
  namespace: string,
) => any;

type nullish = null | undefined | void;

export type MergeObjects<
  Destination extends Input,
  Defaults extends Input,
> = Destination extends Defaults
  ? Destination
  : Omit<Destination, keyof Destination & keyof Defaults> &
      Omit<Defaults, keyof Destination & keyof Defaults> & {
        -readonly [Key in keyof Destination & keyof Defaults]: Destination[Key] extends nullish
          ? Defaults[Key] extends nullish
            ? nullish
            : Defaults[Key]
          : Defaults[Key] extends nullish
            ? Destination[Key]
            : Merge<Destination[Key], Defaults[Key]>; // eslint-disable-line no-use-before-define
      };

export type Defu<S extends Input, D extends Array<Input | IgnoredInput>> = D extends [
  infer F,
  ...infer Rest,
]
  ? F extends Input
    ? Rest extends Array<Input | IgnoredInput>
      ? Defu<MergeObjects<S, F>, Rest>
      : MergeObjects<S, F>
    : F extends IgnoredInput
      ? Rest extends Array<Input | IgnoredInput>
        ? Defu<S, Rest>
        : S
      : S
  : S;

export type DefuFn = <Source extends Input, Defaults extends Array<Input | IgnoredInput>>(
  source: Source,
  ...defaults: Defaults
) => Defu<Source, Defaults>;

export interface DefuInstance {
  <Source extends Input, Defaults extends Array<Input | IgnoredInput>>(
    source: Source | IgnoredInput,
    ...defaults: Defaults
  ): Defu<Source, Defaults>;
  fn: DefuFn;
  arrayFn: DefuFn;
  extend(merger?: Merger): DefuFn;
}

export type MergeArrays<Destination, Source> =
  Destination extends Array<infer DestinationType>
    ? Source extends Array<infer SourceType>
      ? Array<DestinationType | SourceType>
      : Source | Array<DestinationType>
    : Source | Destination;

export type Merge<Destination extends Input, Defaults extends Input> =
  // Remove explicitly null types
  Destination extends nullish
    ? Defaults extends nullish
      ? nullish
      : Defaults
    : Defaults extends nullish
      ? Destination
      : // Handle arrays
        Destination extends Array<any>
        ? Defaults extends Array<any>
          ? MergeArrays<Destination, Defaults>
          : Destination | Defaults
        : // Don't attempt to merge Functions, RegExps, Promises
          // eslint-disable-next-line @typescript-eslint/ban-types
          Destination extends Function
          ? Destination | Defaults
          : Destination extends RegExp
            ? Destination | Defaults
            : Destination extends Promise<any>
              ? Destination | Defaults
              : // Don't attempt to merge Functions, RegExps, Promises
                // eslint-disable-next-line @typescript-eslint/ban-types
                Defaults extends Function
                ? Destination | Defaults
                : Defaults extends RegExp
                  ? Destination | Defaults
                  : Defaults extends Promise<any>
                    ? Destination | Defaults
                    : // Ensure we only merge Records
                      Destination extends Input
                      ? Defaults extends Input
                        ? MergeObjects<Destination, Defaults>
                        : Destination | Defaults
                      : Destination | Defaults;

// https://github.com/fastify/secure-json-parse
// https://github.com/hapijs/bourne
const suspectProtoRx =
  /"(?:_|\\u0{2}5[Ff]){2}(?:p|\\u0{2}70)(?:r|\\u0{2}72)(?:o|\\u0{2}6[Ff])(?:t|\\u0{2}74)(?:o|\\u0{2}6[Ff])(?:_|\\u0{2}5[Ff]){2}"\s*:/;
const suspectConstructorRx =
  /"(?:c|\\u0063)(?:o|\\u006[Ff])(?:n|\\u006[Ee])(?:s|\\u0073)(?:t|\\u0074)(?:r|\\u0072)(?:u|\\u0075)(?:c|\\u0063)(?:t|\\u0074)(?:o|\\u006[Ff])(?:r|\\u0072)"\s*:/;

const JsonSigRx = /^\s*["[{]|^\s*-?\d{1,16}(\.\d{1,17})?([Ee][+-]?\d+)?\s*$/;

function jsonParseTransform(key: string, value: any): any {
  if (
    key === "__proto__" ||
    (key === "constructor" &&
      value &&
      typeof value === "object" &&
      "prototype" in value)
  ) {
    warnKeyDropped(key);
    return;
  }
  return value;
}

function warnKeyDropped(key: string): void {
  console.warn(`[destr] Dropping "${key}" key to prevent prototype pollution.`);
}

export type Options = {
  strict?: boolean;
};

export function destr<T = unknown>(value: any, options: Options = {}): T {
  if (typeof value !== "string") {
    return value;
  }
  if (
    value[0] === '"' &&
    value[value.length - 1] === '"' &&
    value.indexOf("\\") === -1
  ) {
    return value.slice(1, -1) as T;
  }

  const _value = value.trim();

  if (_value.length <= 9) {
    switch (_value.toLowerCase()) {
      case "true": {
        return true as T;
      }
      case "false": {
        return false as T;
      }
      case "undefined": {
        return undefined as T;
      }
      case "null": {
        return null as T;
      }
      case "nan": {
        return Number.NaN as T;
      }
      case "infinity": {
        return Number.POSITIVE_INFINITY as T;
      }
      case "-infinity": {
        return Number.NEGATIVE_INFINITY as T;
      }
    }
  }

  if (!JsonSigRx.test(value)) {
    if (options.strict) {
      throw new SyntaxError("[destr] Invalid JSON");
    }
    return value as T;
  }

  try {
    if (suspectProtoRx.test(value) || suspectConstructorRx.test(value)) {
      if (options.strict) {
        throw new Error("[destr] Possible prototype pollution");
      }
      return JSON.parse(value, jsonParseTransform);
    }
    return JSON.parse(value);
  } catch (error) {
    if (options.strict) {
      throw error;
    }
    return value as T;
  }
}

export function safeDestr<T = unknown>(value: any, options: Options = {}): T {
  return destr<T>(value, { ...options, strict: true });
}

export default destr;

import type { Hookable } from "./hookable.ts";

export interface CreateDebuggerOptions {
  /** An optional tag to prefix console logs with */
  tag?: string;

  /**
   * Show hook params to the console output
   *
   * Enabled for browsers by default
   */
  inspect?: boolean;

  /**
   * Use group/groupEnd wrapper around logs happening during a specific hook
   *
   * Enabled for browsers by default
   */
  group?: boolean;

  /** Filter which hooks to enable debugger for. Can be a string prefix or fn. */
  filter?: string | ((event: string) => boolean);
}

// eslint-disable-next-line unicorn/prefer-global-this
const isBrowser = typeof window !== "undefined";

/** Start debugging hook names and timing in console */
export function createDebugger(
  hooks: Hookable<any>,
  _options: CreateDebuggerOptions = {},
): {
  /** Stop debugging and remove listeners */
  close: () => void;
} {
  const options = {
    inspect: isBrowser,
    group: isBrowser,
    filter: () => true,
    ..._options,
  } satisfies CreateDebuggerOptions;

  const _filter = options.filter;
  const filter = typeof _filter === "string" ? (name: string) => name.startsWith(_filter) : _filter;

  const _tag = options.tag ? `[${options.tag}] ` : "";
  const logPrefix = (event: any) => _tag + event.name + "".padEnd(event._id, "\0");

  const _idCtr: Record<string, number> = {};

  // Before each
  const unsubscribeBefore = hooks.beforeEach((event: any) => {
    if (filter !== undefined && !filter(event.name)) {
      return;
    }
    _idCtr[event.name] = _idCtr[event.name] || 0;
    event._id = _idCtr[event.name]++;
    console.time(logPrefix(event));
  });

  // After each
  const unsubscribeAfter = hooks.afterEach((event) => {
    if (filter !== undefined && !filter(event.name)) {
      return;
    }
    if (options.group) {
      console.groupCollapsed(event.name);
    }
    if (options.inspect) {
      console.timeLog(logPrefix(event), event.args);
    } else {
      console.timeEnd(logPrefix(event));
    }
    if (options.group) {
      console.groupEnd();
    }
    _idCtr[event.name]--;
  });

  return {
    /** Stop debugging and remove listeners */
    close: () => {
      unsubscribeBefore();
      unsubscribeAfter();
    },
  };
}

import {
  flatHooks,
  parallelTaskCaller,
  serialTaskCaller,
  callEachWith,
  callHooks,
} from "./utils.ts";

import type { DeprecatedHook, NestedHooks, HookCallback, HookKeys } from "./types.ts";

type InferCallback<HT, HN extends keyof HT> = HT[HN] extends HookCallback ? HT[HN] : never;
type InferSpyEvent<HT extends Record<string, any>> = {
  [key in keyof HT]: {
    name: key;
    args: Parameters<HT[key]>;
    context: Record<string, any>;
  };
}[keyof HT];

export class Hookable<
  HooksT extends Record<string, any> = Record<string, HookCallback>,
  HookNameT extends HookKeys<HooksT> = HookKeys<HooksT>,
> {
  private _hooks: { [key: string]: HookCallback[] | undefined };
  private _before?: HookCallback[];
  private _after?: HookCallback[];
  private _deprecatedHooks: Record<string, DeprecatedHook<HooksT>>;
  private _deprecatedMessages?: Set<string>;

  constructor() {
    this._hooks = {};
    this._before = undefined;
    this._after = undefined;
    this._deprecatedMessages = undefined;
    this._deprecatedHooks = {};

    // Allow destructuring hook and callHook functions out of instance object
    this.hook = this.hook.bind(this);
    this.callHook = this.callHook.bind(this);
    this.callHookWith = this.callHookWith.bind(this);
  }

  hook<NameT extends HookNameT>(
    name: NameT,
    function_: InferCallback<HooksT, NameT>,
    options: { allowDeprecated?: boolean } = {},
  ): () => void {
    if (!name || typeof function_ !== "function") {
      return () => {};
    }

    const originalName = name;
    let dep: DeprecatedHook<HooksT> | undefined;
    while (this._deprecatedHooks[name]) {
      dep = this._deprecatedHooks[name];
      name = dep.to as NameT;
    }
    if (dep && !options.allowDeprecated) {
      let message = dep.message;
      if (!message) {
        message =
          `${originalName} hook has been deprecated` + (dep.to ? `, please use ${dep.to}` : "");
      }
      if (!this._deprecatedMessages) {
        this._deprecatedMessages = new Set();
      }
      if (!this._deprecatedMessages.has(message)) {
        console.warn(message);
        this._deprecatedMessages.add(message);
      }
    }

    // Add name to hook for better debugging experience
    if (!function_.name) {
      try {
        Object.defineProperty(function_, "name", {
          get: () => "_" + name.replace(/\W+/g, "_") + "_hook_cb",
          configurable: true,
        });
      } catch {
        // ignore
      }
    }

    this._hooks[name] = this._hooks[name] || [];
    this._hooks[name]!.push(function_);

    return () => {
      if (function_) {
        this.removeHook(name, function_);
        // @ts-ignore
        function_ = undefined; // Free memory
      }
    };
  }

  hookOnce<NameT extends HookNameT>(
    name: NameT,
    function_: InferCallback<HooksT, NameT>,
  ): () => void {
    let _unreg: (() => void) | undefined;
    let _function: ((...arguments_: any) => any) | undefined = (...arguments_: any) => {
      if (typeof _unreg === "function") {
        _unreg();
      }
      _unreg = undefined;
      _function = undefined;
      return function_(...arguments_);
    };
    _unreg = this.hook(name, _function as typeof function_);
    return _unreg;
  }

  removeHook<NameT extends HookNameT>(name: NameT, function_: InferCallback<HooksT, NameT>): void {
    const hooks = this._hooks[name];

    if (hooks) {
      const index = hooks.indexOf(function_);

      if (index !== -1) {
        hooks.splice(index, 1);
      }

      if (hooks.length === 0) {
        this._hooks[name] = undefined;
      }
    }
  }

  clearHook<NameT extends HookNameT>(name: NameT): void {
    this._hooks[name] = undefined;
  }

  deprecateHook<NameT extends HookNameT>(
    name: NameT,
    deprecated: HookKeys<HooksT> | DeprecatedHook<HooksT>,
  ): void {
    this._deprecatedHooks[name] = typeof deprecated === "string" ? { to: deprecated } : deprecated;
    const _hooks = this._hooks[name] || [];
    this._hooks[name] = undefined;
    for (const hook of _hooks) {
      this.hook(name, hook as any);
    }
  }

  deprecateHooks(deprecatedHooks: Partial<Record<HookNameT, DeprecatedHook<HooksT>>>): void {
    for (const name in deprecatedHooks) {
      this.deprecateHook(name, deprecatedHooks[name] as DeprecatedHook<HooksT>);
    }
  }

  addHooks(configHooks: NestedHooks<HooksT>): () => void {
    const hooks = flatHooks<HooksT>(configHooks);
    // @ts-ignore
    const removeFns = Object.keys(hooks).map((key) => this.hook(key as HookNameT, hooks[key]));

    return () => {
      for (const unreg of removeFns) {
        unreg();
      }

      // Ensures that all fns are called once, and free all
      // unreg functions from memory.
      removeFns.length = 0;
    };
  }

  removeHooks(configHooks: NestedHooks<HooksT>): void {
    const hooks = flatHooks<HooksT>(configHooks);
    for (const key in hooks) {
      // @ts-ignore
      this.removeHook(key, hooks[key]);
    }
  }

  removeAllHooks(): void {
    this._hooks = {};
  }

  callHook<NameT extends HookNameT>(
    name: NameT,
    ...args: Parameters<InferCallback<HooksT, NameT>>
  ): Promise<any> | void {
    return this.callHookWith(serialTaskCaller, name, args);
  }

  callHookParallel<NameT extends HookNameT>(
    name: NameT,
    ...args: Parameters<InferCallback<HooksT, NameT>>
  ): Promise<any[]> | void {
    return this.callHookWith(parallelTaskCaller, name, args);
  }

  callHookWith<
    NameT extends HookNameT,
    CallFunction extends (
      hooks: HookCallback[],
      args: Parameters<InferCallback<HooksT, NameT>>,
      name: NameT,
    ) => any,
  >(
    caller: CallFunction,
    name: NameT,
    args: Parameters<InferCallback<HooksT, NameT>>,
  ): ReturnType<CallFunction> {
    const event = this._before || this._after ? { name, args, context: {} } : undefined;
    if (this._before) {
      callEachWith(this._before, event);
    }
    const result = caller(
      this._hooks[name] ? [...this._hooks[name]] : [],
      args as Parameters<InferCallback<HooksT, NameT>>,
      name,
    );
    if ((result as any) instanceof Promise) {
      return result.finally(() => {
        if (this._after && event) {
          callEachWith(this._after, event);
        }
      });
    }
    if (this._after && event) {
      callEachWith(this._after, event);
    }
    return result;
  }

  beforeEach(function_: (event: InferSpyEvent<HooksT>) => void): () => void {
