      );
      let content = `${type}{`;
      for (let i = 0; i < sortedEntries.length; i++) {
        const [key, value] = sortedEntries[i];
        content += `${this.serialize(key, true)}:${this.serialize(value)}`;
        if (i < sortedEntries.length - 1) {
          content += ",";
        }
      }
      return content + "}";
    }

    $object(object: any) {
      let content = this.#context.get(object);

      if (content === undefined) {
        this.#context.set(object, `#${this.#context.size}`);
        content = this.serializeObject(object);
        this.#context.set(object, content);
      }

      return content;
    }

    $function(fn: any) {
      const fnStr = Function.prototype.toString.call(fn);
      if (
        fnStr.slice(-15 /* "[native code] }".length */) === "[native code] }"
      ) {
        return `${fn.name || ""}()[native]`;
      }
      return `${fn.name}(${fn.length})${fnStr.replace(/\s*\n\s*/g, "")}`;
    }

    $Array(arr: any[]) {
      let content = "[";
      for (let i = 0; i < arr.length; i++) {
        content += this.serialize(arr[i]);
        if (i < arr.length - 1) {
          content += ",";
        }
      }
      return content + "]";
    }

    $Date(date: any) {
      try {
        return `Date(${date.toISOString()})`;
      } catch {
        return `Date(null)`;
      }
    }

    $ArrayBuffer(arr: ArrayBuffer) {
      return `ArrayBuffer[${new Uint8Array(arr).join(",")}]`;
    }

    $Set(set: Set<any>) {
      return `Set${this.$Array(Array.from(set).sort((a, b) => this.compare(a, b)))}`;
    }

    $Map(map: Map<any, any>) {
      return this.serializeObjectEntries("Map", map.entries());
    }
  }

  for (const type of ["Error", "RegExp", "URL"] as const) {
    // @ts-ignore
    Serializer.prototype["$" + type] = function (val: any) {
      return `${type}(${val})`;
    };
  }

  for (const type of [
    "Int8Array",
    "Uint8Array",
    "Uint8ClampedArray",
    "Int16Array",
    "Uint16Array",
    "Int32Array",
    "Uint32Array",
    "Float32Array",
    "Float64Array",
  ] as const) {
    // @ts-ignore
    Serializer.prototype["$" + type] = function (arr: TypedArray) {
      return `${type}[${arr.join(",")}]`;
    };
  }

  for (const type of ["BigInt64Array", "BigUint64Array"] as const) {
    // @ts-ignore
    Serializer.prototype["$" + type] = function (arr: TypedArray) {
      return `${type}[${arr.join("n,")}${arr.length > 0 ? "n" : ""}]`;
    };
  }
  return Serializer;
})();

import { serialize } from "../serialize";

/**
 * `__proto__` is never traversed or reported as a diff key.
 *
 * A `for..in` over `JSON.parse('{"__proto__": 1}')` does yield `__proto__` as an
 * own enumerable property, but surfacing it would (a) let a diff entry become a
 * prototype-pollution write for any consumer that replays entries with
 * `target[entry.key] = value`, and (b) let an assignment into a `props` record
 * silently reassign that record's prototype. Excluding it keeps a diff key
 * always safe to assign.
 */
const PROTO_KEY = "__proto__";

/**
 * Calculates the difference between two objects and returns a list of differences.
 *
 * @param {any} obj1 - The first object to compare.
 * @param {any} obj2 - The second object to compare.
 * @returns {DiffEntry[]} An array with the differences between the two objects.
 */
export function diff(obj1: any, obj2: any): DiffEntry[] {
  const diffs: DiffEntry[] = [];
  _diff(obj1, obj2, "", diffs);
  return diffs;
}

/**
 * Recursively diffs two values in a single fused traversal.
 *
 * Reference-equal (or primitive-equal) values share no differences, so entire
 * subtrees are skipped via the `v1 === v2` short-circuit without ever visiting
 * them. Entries are appended to the shared `out` accumulator so that no
 * intermediate array is allocated or re-copied per recursion level.
 */
function _diff(v1: any, v2: any, key: string, out: DiffEntry[]): void {
  if (v1 === v2) {
    return;
  }

  // Only non-null objects and arrays are "containers" (enumerated via
  // `for..in`); every primitive is a leaf, including falsy ones and `null`.
  const leaf1 = v1 === null || typeof v1 !== "object";
  const leaf2 = v2 === null || typeof v2 !== "object";

  if (!leaf1 && !leaf2) {
    // Each value is read inside the same `for..in` pass that yields its key.
    // Reading keys first and values later would let a getter that mutates its
    // own object (deleting a sibling, truncating an array) produce entries for
    // keys that no longer exist by the time they are read.
    const entries1 = _entries(v1);
    const entries2 = _entries(v2);
    for (const [k, child1] of entries1) {
      const childKey = key ? `${key}.${k}` : k;
      if (entries2.has(k)) {
        _diff(child1, entries2.get(k), childKey, out);
      } else {
        out.push(
          new DiffEntry(
            childKey,
            "removed",
            undefined,
            _toHashedObject(child1, childKey),
          ),
        );
      }
    }
    for (const [k, child2] of entries2) {
      if (entries1.has(k)) {
        continue;
      }
      const childKey = key ? `${key}.${k}` : k;
      out.push(
        new DiffEntry(childKey, "added", _toHashedObject(child2, childKey)),
      );
    }
    // Two containers with no enumerable keys both hash to `{}`, so nothing is
    // emitted for them here.
    return;
  }

  // Mixed (leaf vs container) or both leaves: a "changed" entry is only emitted
  // when neither side has enumerable keys — i.e. both leaves, or a leaf vs an
  // empty container. A leaf vs a non-empty container yields nothing.
  if (_hasKeys(v1, leaf1) || _hasKeys(v2, leaf2)) {
    return;
  }
  // Neither side has keys, so both nodes are cheap to build directly; calling
  // `_toHashedObject` here would re-run `for..in` over each value a second time.
  const node1 = _emptyOrLeafNode(v1, key, leaf1);
  const node2 = _emptyOrLeafNode(v2, key, leaf2);
  if (node1.hash !== node2.hash) {
    out.push(new DiffEntry(key, "changed", node2, node1));
  }
}

/**
 * Snapshots a container's enumerable entries, reading every value in the same
 * pass that yields its key. A `Map` is used so that keys colliding with
 * `Object.prototype` members (`toString`, `constructor`, ...) are handled by
 * value rather than resolving to an inherited member.
 */
function _entries(value: any): Map<string, any> {
  const entries = new Map<string, any>();
  for (const key in value) {
    if (key !== PROTO_KEY) {
      entries.set(key, value[key]);
    }
  }
  return entries;
}

/**
 * Whether a container has at least one enumerable key. Stops at the first one
 * rather than counting them all.
 */
function _hasKeys(value: any, isLeaf: boolean): boolean {
  if (isLeaf) {
    return false;
  }
  for (const key in value) {
    if (key !== PROTO_KEY) {
      return true;
    }
  }
  return false;
}

/** Builds a node for a leaf, or for a container already known to have no keys. */
function _emptyOrLeafNode(
  value: any,
  key: string,
  isLeaf: boolean,
): DiffHashedObject {
  return isLeaf
    ? new DiffHashedObject(key, value, _leafHash(value))
    : new DiffHashedObject(key, value, "{}", Object.create(null));
}

function _toHashedObject(obj: any, key = ""): DiffHashedObject {
  if (obj === null || typeof obj !== "object") {
    return new DiffHashedObject(key, obj, _leafHash(obj));
  }
  // A null-prototype record so that a key colliding with an `Object.prototype`
  // member is stored and read back as its own value.
  const props: Record<string, DiffHashedObject> = Object.create(null);
  const hashes: (string | undefined)[] = [];
  for (const _key in obj) {
    if (_key === PROTO_KEY) {
      continue;
    }
    const child = _toHashedObject(obj[_key], key ? `${key}.${_key}` : _key);
    props[_key] = child;
    hashes.push(child.hash);
  }
  return new DiffHashedObject(key, obj, `{${hashes.join(":")}}`, props);
}

/**
 * Serializes a primitive leaf value for diffing.
 *
 * Avoids allocating a full `Serializer` (and its backing `Map`) per leaf for
 * the common primitive cases, falling back to {@link serialize} only for
 * functions and symbols.
 */
function _leafHash(value: any): string {
  switch (typeof value) {
    case "string": {
      return `'${value}'`;
    }
    case "number":
    case "boolean": {
      return "" + value;
    }
    case "bigint": {
      return `${value}n`;
    }
    default: {
      return serialize(value);
    }
  }
}

// --- Internal classes ---

export class DiffEntry {
  constructor(
    public key: string,
    public type: "changed" | "added" | "removed",
    public newValue?: DiffHashedObject,
    public oldValue?: DiffHashedObject,
  ) {}

  toString() {
    return this.toJSON();
  }

  toJSON() {
    switch (this.type) {
      case "added": {
        return `Added   \`${this.key}\``;
      }
      case "removed": {
        return `Removed \`${this.key}\``;
      }
      case "changed": {
        return `Changed \`${this.key}\` from \`${
          this.oldValue?.toString() || "-"
        }\` to \`${this.newValue?.toString()}\``;
      }
    }
  }
}

export class DiffHashedObject {
  constructor(
    public key: string,
    public value: any,
    public hash?: string,
    public props?: Record<string, DiffHashedObject>,
  ) {}

  toString() {
    if (this.props) {
      return `{${Object.keys(this.props).join(",")}}`;
    } else {
      return JSON.stringify(this.value);
    }
  }

  toJSON() {
    const k = this.key || ".";
    if (this.props) {
      return `${k}({${Object.keys(this.props).join(",")}})`;
    }
    return `${k}(${this.value})`;
  }
}

import { serialize } from "../serialize";
/**
 * Compare two objects using reference equality and stable deep hashing.
 * @param {any} object1 First object
 * @param {any} object2 Second object
 * @return {boolean} true if equal and false if not
 */
export function isEqual(object1: any, object2: any): boolean {
  if (object1 === object2) {
    return true;
  }
  if (serialize(object1) === serialize(object2)) {
    return true;
  }
  return false;
}

import {
  absolutePattern,
  DOT_SEGMENT,
  DOT_SEGMENT_NEXT_TO,
  invalidSyntax,
  MISPLACED_MODIFIER,
} from "./_pattern.ts";

/** `[pre, body, suf, mod]` split of a `{...}` group, or `undefined`. */
export type GroupDelimiter = [pre: string, body: string, suf: string, mod: string | undefined];

/**
 * Locate the first top-level `{...}` group delimiter (skipping `\` escapes and
 * capturing-group parens) and split into `[pre, body, suf, mod]`. Returns
 * `undefined` when there is no top-level group.
 *
 * Shared by {@link expandGroupDelimiters} (tree add/remove/expansion) and
 * `routeToRegExp()`'s inline-optional compiler so both classify groups
 * identically. Returns a tuple (not an object) to stay tiny in the core bundle.
 */
export function scanFirstGroup(path: string): GroupDelimiter | undefined {
  let i = 0;
  let depth = 0;
  for (; i < path.length; i++) {
    const c = path.charCodeAt(i);
    if (c === 92 /* \ */) i++;
    else if (c === 40 /* ( */) depth++;
    else if (c === 41 /* ) */ && depth > 0) depth--;
    else if (c === 123 /* { */ && depth === 0) break;
  }
  if (i >= path.length) return;

  let j = i + 1;
  depth = 0;
  for (; j < path.length; j++) {
    const c = path.charCodeAt(j);
    if (c === 92 /* \ */) j++;
    else if (c === 40 /* ( */) depth++;
    else if (c === 41 /* ) */ && depth > 0) depth--;
    else if (c === 125 /* } */ && depth === 0) break;
  }
  if (j >= path.length) return;

  const mod = path[j + 1];
  const hasMod = mod === "?" || mod === "+" || mod === "*";
  // A `{` / `}` ends a param name, as in URLPattern: the char after one is
  // escaped where it could extend a name once expanded (`/:a{b}?` is `/:a\b`
  // or `/:a`). A `\x` there is always a literal `x` (`body` and `suf` start
  // outside any constraint), so this is a no-op after anything else.
  return [
    path.slice(0, i),
    path.slice(i + 1, j).replace(NAME_CHAR, "\\$&"),
    path.slice(j + (hasMod ? 2 : 1)).replace(NAME_CHAR, "\\$&"),
    hasMod ? mod : undefined,
  ];
}

// A char that would extend a `:name` (a `$` or non-ASCII one there throws)
const NAME_CHAR = /^[\w$\x80-￼]/;

/**
 * Expand the first `{...}` / `{...}?` group of `path` into the routes it
 * stands for. `{...}+` / `{...}*` repetition is not supported: `input` (quoted
 * in the error) is rejected.
 *
 * A pattern starting with a group gets no `/` in front (see `addRoute`): each
 * expansion is read on its own. One starting with `/` is absolute, as in
 * URLPattern (`{/:a}?/b` is `/:a/b` or `/b`); any other one, the empty one
 * too, is relative and gets a `/` like a pattern (`{a}?/b` is `/a/b` or `/b`,
 * `{/:a}?` is `/:a` or `/`). One starting with `{` is left to the next group.
 * Text right after a leading `{/…}?` (`{/a}?b`, `{/:a}?.png`, `{/a}?{b}?/c`)
 * throws: without the group the route would be relative, a form URLPattern
 * gives no meaning (it matches only `/ab`), so a `/b` would be a guess.
 */
export function expandGroupDelimiters(path: string, input: string = path): string[] | undefined {
  if (!path.includes("{")) return;
  const group = scanFirstGroup(path);
  if (!group) {
    return;
  }

  const [pre, body, suf, mod] = group;

  if (mod === "+" || mod === "*") {
    invalidSyntax(`unsupported \`{}${mod}\``, input);
  }

  // An optional lone param after text, ending its segment (`*-{:x}?`,
  // `pre{:x(\d+)}?`), is `:x?` there, as in URLPattern: `getParamRegexp`
  // compiles it in place after a capture, `expandModifiers` expands it after
  // text. One that starts its segment (`/{:x}?`) is a group, and so is one
  // in a `**` segment, which has no text (`/a/**{:x}?` is `/a/**:x` or
  // `/a/**`; an escaped `\**` is text). (A name char starting `suf` is
  // escaped, so it can't end the name.)
  if (
    mod === "?" &&
    /^(?!\*\*)./.test(pre.slice(pre.lastIndexOf("/") + 1)) &&
    /^:[A-Za-z_]\w*(\([^)]*\))?$/.test(body) &&
    (!suf || suf[0] === "/")
  ) {
    // Alone: the caller expands (and numbers, `skipGroup`) the next group
    return [pre + body + "?" + suf];
  }

  const full = joinGroup(joinGroup(pre, body, input), suf, input);
  const expanded = mod ? [full, joinGroup(pre, suf, input)] : [full];
  // A `.` / `..` segment left after `dotSegments` is in a group or touches
  // one (`/a{/..}?/b`, `/a/{.}./b`): URLPattern resolves the group's text on
  // its own (`/a{/}?/b`), no path rule
  if (expanded.some((e) => DOT_SEGMENT.test(e))) invalidSyntax(DOT_SEGMENT_NEXT_TO, input);
  if (pre) return expanded;
  // After a leading `{/…}?`: `/`, another `{/…}` group or nothing
  if (mod && body.charCodeAt(0) === 47 /* '/' */ && suf && !/^\{?\//.test(suf)) {
    invalidSyntax("text after a leading `{/...}?`", input);
  }
  return expanded.map(absolutePattern);
}

/**
 * `a` + `b`, two parts of a route a `{` / `}` stood between. A `{` / `}` ends
 * a param name (see {@link scanFirstGroup}), so where `a` ends in a bare
 * `:name` and `b` starts with a regex group, the group is an unnamed capture
 * next to the param, as in URLPattern, not its constraint: the param gets the
 * lazy constraint a `:name` sharing its segment has anyway (`[^/]+?`, spelled
 * without a `/`, which would split the segment). A `?` / `+` / `*` there, or
 * after a constraint, group or `*`, would be a modifier on it (`/*{*}` a
 * `**`), which it is not in URLPattern: `input` (quoted in the error) is
 * rejected.
 */
export function joinGroup(a: string, b: string, input?: string): string {
  // `a` ends in a `:name` (not a `**:name`, which ends its segment anyway; an
  // invalid name throws later), a group of its segment (a stray `)` is a
  // literal) or a `*`, none escaped, and `b` starts with a `(`, `?`, `+` or
  // `*` (an empty `b` appends `"undefined"`, which ends in none of them), or
  // with the U+FFFF before a `(.*)` group's `*` (see `starGroups`), which
  // stays there only (so the `*` is no modifier)
  const m = /(?<!\\)(\\\\)*((?<!\*\*):\w+|\([^/]*[^\\]\)|\*)([(?+*\uFFFF])$/.exec(a + b[0]);
  if (m) {
    if (m[3] === "\uFFFF") return a + b;
    // `m[3]` is no `(` (`?`, `+` and `*` sort after it)
    if (m[3] > "(") invalidSyntax(MISPLACED_MODIFIER, input!);
    // Only a `:name` starts with a char after `*` (`(` and `*` don't)
    if (m[2] > "*") a += "([^\\x2f]+?)";
  }
  return a + (b.charCodeAt(0) === 0xffff ? b.slice(1) : b);
}

// Route param names are identifiers (`[A-Za-z_]\w*`), but `_N`-shaped ones
// collide with the unnamed captures `routeToRegExp` emits and `__rou3_` ones with
// the internal prefixes. Those are escaped into a reserved form, and decoded back
// when groups are read: params always surface under the original route name
// (`:_0` -> `params._0`). The codec stays total for any string (a `-` or leading
// digit is escaped too), so older regexes and `regExpToRoute` input decode.
//
// The escape is a prefix code (every `_` in the output opens a two-char escape),
// so it is injective: distinct names can never collide (`a-b`, `a_b`, `a--b`
// stay distinct, unlike a plain `-` -> `_` sanitize) and decoding is exact. It
// stays inside `[A-Za-z0-9_]`, so the output is a legal PCRE group name too.

export const UNNAMED_GROUP_PREFIX = "__rou3_unnamed_";

export const ESCAPED_GROUP_PREFIX = "__rou3_esc_";

/** The group name of an unnamed capture's key (a `:name(.*)`'s is its name). */
export function toUnnamedGroupKey(key: number | string): string {
  return typeof key === "string" ? toGroupName(key) : `${UNNAMED_GROUP_PREFIX}${key}`;
}

/**
 * Encode a param name as a capture-group name. Valid identifiers pass through
 * unchanged (the common case); the rest are escaped (`_` -> `__`, `-` -> `_h`)
 * behind {@link ESCAPED_GROUP_PREFIX}. Names in the reserved `__rou3_` space, and
 * `_N`-shaped ones (the unnamed-capture form `routeToRegExp` emits), are escaped
 * too, so a group name maps back to exactly one param name.
 */
export function toGroupName(name: string): string {
  return /^(?!__rou3_|_\d)[A-Za-z_]\w*$/.test(name)
    ? name
    : ESCAPED_GROUP_PREFIX + name.replace(/[_-]/g, (c) => (c === "_" ? "__" : "_h"));
}

/** Decode a capture-group name into its param name (inverse of {@link toGroupName}). */
export function fromGroupName(key: string): string {
  if (key.charCodeAt(0) !== 95 /* `_` */) {
    return key; // fast path: not in the reserved space
  }
  if (key.startsWith(ESCAPED_GROUP_PREFIX)) {
    return key
      .slice(ESCAPED_GROUP_PREFIX.length)
      .replace(/__|_h/g, (c) => (c === "__" ? "_" : "-"));
  }
  return key.startsWith(UNNAMED_GROUP_PREFIX) ? key.slice(UNNAMED_GROUP_PREFIX.length) : key;
}

import { fromGroupName } from "./_group-names.ts";
import { NullProtoObj } from "./object.ts";
import type { MatchedRoute, MethodData, ParamsIndexMap } from "./types.ts";

// Lookup-time helpers shared by `findRoute`, `findAllRoutes` and the compiler
// (and `splitPath` by `splitRoute`): path normalization and splitting, entry
// order on a node, and params.

/**
 * Whether matching `m` on `segments` gives a `:name` an empty segment, or a
 * `**:name` (`:name+`, `:name*`) an empty one among those it takes: every
 * segment needs a value, as in URLPattern (`[^/]+(?:/[^/]+)*`). A `*` (also a
 * `:name(.*)`, any segment of it), a `**` and a constraint (it decides:
 * `:id(\d*)`) may be empty. Callers check only paths with an empty segment.
 */
export function emptyParam(m: MethodData<unknown>, segments: string[]): boolean {
  const pMap = m.paramsMap;
  const params = pMap && getMatchParams(segments, pMap, m.suffix)!;
  // A `*` (also a `:name(.*)`) is `empty`, a bare `**` is named by a digit
  // and a constraint is a RegExp (`/^…$/`), both `< ":"`. A value holds an
  // empty segment where it is `""`, or starts, ends or holds `//` (a
  // `:name`'s has no `/`).
  return !!pMap?.some(
    ([, name, , empty]) =>
      !empty && (name as string) > ":" && /(^|\/)(\/|$)/.test(params![name as string]),
  );
}

/**
 * Whether entry `m` of a wildcard node (a route ending in its catch-all)
 * matches zero segments there: a bare `**` (`optional`) and a `*` (`empty`,
 * also a `:name(.*)`; not the `**` of a split one), not a `**:name`. A
 * trailing `*` is optional, as in 0.11: `/foo/*` matches `/foo` (no key, see
 * `getMatchParams`) and `/foo/` (`""`).
 */
export function matchesZero(m: MethodData<unknown>): boolean {
  const last = m.paramsMap![m.paramsMap!.length - 1];
  return last[2] || (!!last[3] && !last[5]);
}

export function normalizePath(path: string): string {
  if (!path.includes("/.")) return path;
  const r: string[] = [];
  let s = "";
  for (s of path.split("/")) {
    if (s === ".") continue;
    // r[0] is the leading "" — a ".." at the root is a no-op, never a literal
    else if (s === "..") {
      if (r.length > 1) r.pop();
    } else r.push(s);
  }
  // A last `.` / `..` leaves a trailing slash, as in WHATWG (`/a/b/..` is
  // `/a/`, which a `/a/*` matches)
  if (s === "." || s === "..") r.push("");
  return r.join("/") || "/";
}

/**
 * Split a lookup path (already stripped of its one ignored trailing `/`) into
 * segments. Empty segments are kept: `/a/` is `["a", ""]` (#209).
 */
export function splitPath(path: string): string[] {
  const s = path.split("/");
  s.shift();
  return s;
}

/**
 * A node's entries for `method`, least -> most specific on equal weight: the
 * method-agnostic (`""`) ones, then the method's own. Both are siblings on the
 * node (a method-scoped entry must never hide a `""` one), and callers order
 * them by weight with a stable sort. `reverse` flips each bucket (same-node
 * ties go to the first-registered in findRoute).
 */
export function methodEntries<T>(
  methods: Record<string, MethodData<T>[] | undefined>,
  method: string,
  reverse?: boolean,
): MethodData<T>[] | undefined {
  let own = methods[method];
  let any = method ? methods[""] : undefined;
  if (reverse) {
    own &&= own.slice().reverse();
    any &&= any.slice().reverse();
  }
  return own && any ? any.concat(own) : own || any;
}

/**
 * Same-node `entries` in registration order, each run of one route's variants
 * (`variants`, added together) reversed: on a tie, `findRoute` picks the
 * first-registered variant, so `findAllRoutes` lists it last of them (the one
 * it keeps), as the `reverse` order does. The input itself when there is none.
 */
export function reverseVariants<T>(entries: MethodData<T>[]): MethodData<T>[] {
  let out: MethodData<T>[] | undefined;
  for (let i = 0, j; i < entries.length; i = j) {
    const token = entries[i].variants;
    for (j = i + 1; token && entries[j]?.variants === token; j++);
    if (j - i > 1) (out ??= entries.slice()).splice(i, j - i, ...entries.slice(i, j).reverse());
  }
  return out || entries;
}

/**
 * A `*` inside a segment is split around a `**` (see `splitStar`): the pieces
 * after its first one (`join`) add theirs after a `/`.
 */
function setParam(
  params: Record<string, string>,
  key: string,
  value: string,
  join?: boolean,
): void {
  params[key] = join && params[key] !== undefined ? params[key] + "/" + value : value;
}

export function getMatchParams(
  segments: string[],
  paramsMap: ParamsIndexMap,
  suffix?: [number, number],
  slash?: boolean,
): MatchedRoute["params"] {
  const params = new NullProtoObj();
  // Segments after a `**` are counted from the end of the path
  const end = suffix ? segments.length - suffix[1] : segments.length;
  for (const [index, name, optional, , , join] of paramsMap) {
    // A bare `**` (`~index` is where it starts; negative for the other
    // params) over zero segments is unset; a trailing `*` there too, unless
    // the lookup path had a trailing slash (`slash`): `""`
    if (~index >= end && (optional || !slash)) continue;
    const segment =
      index < 0
        ? segments.slice(~index, end).join("/")
        : segments[suffix && index > suffix[0] ? index - suffix[0] - 1 + end : index];
    if (typeof name === "string") {
      setParam(params, name, segment, join);
      // A bare `**` is also `_` (deprecated alias, 0.x compatibility)
      if (index < 0 && optional && !join) params._ = segment;
    } else {
      const match = segment.match(name);
      if (match) {
        for (const key in match.groups) {
          // An absent optional (`*-:x?`) has no key
          if (match.groups[key] !== undefined) {
            setParam(params, fromGroupName(key), match.groups[key], join);
          }
        }
      }
    }
  }
  return params;
}

import { splitPath } from "./_match.ts";

// Route pattern preprocessing, shared by everything that reads a pattern
// (`addRoute`, `removeRoute`, `routeToRegExp`, `regExpToRoute`): escapes,
// literal encoding, validation, `(.*)` / dot-segment / modifier / in-segment
// `*` rewrites, and segment keys and route identities.

/**
 * Hide escaped route syntax (`\:` `\(` `\)` `\{` `\}` `\\`) behind U+FFFD +
 * its index in `ESCAPABLE` before splitting, so no later scan reads it as
 * syntax. `\\` is one of them, so escape pairs are read left to right (`\\:x`
 * is a `\` then `:x`). Other `\x` stay: static keys (`segmentKey`) and param
 * segments (`getParamRegexp`) read them as a literal `x`.
 */
export function encodeEscapes(path: string): string {
  if (!path.includes("\\")) return path;
  return path.replace(/\\([:(){}\\])/g, (_, c) => "\uFFFD" + ESCAPABLE.indexOf(c));
}

/** Undo `encodeEscapes`: each placeholder back to its char, after `prefix`. */
export function decodeEscapes(segment: string, prefix: string): string {
  return segment.replace(/\uFFFD([0-5])/g, (_, i) => prefix + ESCAPABLE[i]);
}

// `getParamRegexp` reads placeholders 3 / 4 as `{` / `}`
const ESCAPABLE = ":(){}\\";

/**
 * Where a route-pattern segment goes in the tree, exactly as `addRoute` inserts
 * it: `2` = `node.wildcard` (a catch-all: `**`, `**:name` or a whole-segment
 * `*`), `1` = `node.param`, otherwise the returned string is the
 * `node.static` key: the literal text, where any `\x` is a literal `x`
 * (an escaped `\*` / `\*\*` is the literal `*` / `**`: the escape is what
 * keeps it out of the wildcard/param branches) and `encodeEscapes`'
 * placeholders are their chars again (`:(){}\`), percent-encoded like
 * URLPattern (`encodeLiteral`: `\{` and `é` key as `%7B` and `%C3%A9`).
 *
 * Shared by `addRoute` and `removeRoute`: the two must classify *and* key
 * segments identically, otherwise removal walks to a different — usually
 * nonexistent — node and silently does nothing.
 *
 * Segments after a `**` go into the wildcard node's `suffix` trie instead of
 * its children (see `_add`).
 */
export function segmentKey(segment: string): string | 1 | 2 {
  if (segment === "*" || segment.startsWith("**")) return 2;
  if (segment.includes(":") || segment.includes("(") || segmentWildcards(segment).length > 0) {
    return 1;
  }
  if (segment.includes("\\")) segment = segment.replace(/\\([\s\S])/g, "$1");
  if (segment.includes("\uFFFD")) segment = decodeEscapes(segment, "");
  return encodeLiteral(segment);
}

/**
 * A dynamic (param / wildcard) segment's literal text percent-encoded like
 * `getParamRegexp` does, so `café-:id` and `caf%C3%A9-:id` read as one route
 * (see `routeId`). Constraints are regex and stay as written; `?` / `{` / `}`
 * are syntax here (literal ones are escaped, `encodeEscapes`).
 */
export function dynamicKey(segment: string): string {
  if (!/[\0- "#<>^`\x7F-\uFFFC]/.test(segment)) return segment;
  let d = 0;
  return segment.replace(/[()]|[\0- "#<>^`\x7F-\uFFFC]+/g, (c) =>
    c === "(" ? (d++, c) : c === ")" ? (d && d--, c) : d ? c : encodeLiteral(c),
  );
}

/**
 * A registration identity (`MethodData.route`) in canonical form, for the
 * places that compare them (`removeRoute`, `findOverlappingRoutes`): each
 * segment through `dynamicKey` (a no-op on a static key, already encoded).
 * Kept off `addRoute`, so routers that never compare don't pay for it.
 */
export function routeId(id: string): string {
  return id.split("/").map(dynamicKey).join("/");
}

/**
 * Percent-encode literal pattern text like URLPattern canonicalizes a
 * pathname pattern, so a route matches the encoded pathname `new URL()`
 * gives (lookup paths are never decoded): the URL path percent-encode set
 * (C0 controls, space, `"#<>?^\`{}`, U+007F and up) as UTF-8 `%XX`, a lone
 * surrogate as U+FFFD. A `%` stays, so an existing `%XX` is kept as written.
 * Only for text already read as literal (static keys, `getParamRegexp`): an
 * escape or a `:name` must be parsed first. U+FFFD-U+FFFF are left alone:
 * internal placeholders or reserved (`checkConstraints` rejects them in a
 * route, and a tab / LF / CR, which URLPattern drops).
 */
export function encodeLiteral(text: string): string {
  // A `test` bails early on plain text (a no-match `replace` costs more)
  return /[\0- "#<>?^`{}\x7F-\uFFFC]/.test(text)
    ? text.replace(/[\0- "#<>?^`{}\x7F-\uFFFC]+/g, (run) =>
        encodeURIComponent(run.replace(/[\uD800-\uDFFF]/gu, "\uFFFD")),
      )
    : text;
}

/**
 * Throws on a tab, LF or CR anywhere: URLPattern drops them from a pattern
 * (URL parsing) where `encodeLiteral` would encode them (`%09`), so the same
 * pattern would match other paths, and no pathname has one raw (in a
 * constraint). Throws on U+FFFD-U+FFFF: internal placeholders
 * (`encodeEscapes`, `\uFFFE` in `getParamRegexp`, `\uFFFF` before a `*` in
 * `starGroups`), which a route could otherwise write as syntax (`\uFFFD0`
 * read as an escaped `:`). One check and message for both (bundle size).
 *
 * Throws when a `(...)` group in `route` never closes (`/files/(2024`, #199)
 * or contains a `/` (`:id([^/]+)`): the pattern is split on `/` before groups
 * are read, which cut it in two. Either way `new RegExp` threw a raw
 * `SyntaxError` naming internal group names. Also throws on a `{` / `}` that
 * does not pair up or a nested `{...}` (literals or mis-parsed before), on a
 * `\` that escapes no char of its segment (a `\/` or a trailing `\`), and on
 * a `^` / `$` / look-around in a group: the tree tests a segment on its own,
 * where they see its ends, and `routeToRegExp` inline, where they see the rest
 * of the path (#227), and on a capturing group inside a group (a stray
 * numbered or named param; only `(?:…)` is fine), also inside a class
 * (`[(.*)]`, `[()]`: read as one), and on a `--` / `&&` in a class of a
 * group: URLPattern's `v` flag reads it as a set operation (`[[a-z]--a]`,
 * classes nested), rou3's RegExp as plain chars. Called by `addRoute` (and
 * so by `routeToRegExp`). A stray `)` stays a literal.
 *
 * Escapes are dropped first (`\(` is no group; `\/` stays, the split cuts
 * there too), then balanced `/`-free groups innermost-out (a capturing one
 * leaves a `\0`, like a backreference, in the group around it), so any `(` left does not close in its own segment, and any `\` left
 * escapes nothing. Braces inside a group are regex.
 */
export function checkConstraints(route: string): void {
  if (!/[\t\n\r\\({}\uFFFD-\uFFFF]/.test(route)) return;
  if (/[\t\n\r\uFFFD-\uFFFF]/.test(route)) {
    invalidSyntax("a tab, LF, CR (use %09, %0A, %0D) or U+FFFD-U+FFFF char", route);
  }
  // `\1`-`\9` -> `\0` (a backreference), any other escape -> `_` (a literal,
  // so `\(?=` is no look-ahead)
  let s = route.replace(/\\([^/])/g, (_, c) => (c > "0" && c <= "9" ? "\0" : "_"));
  while (
    s !==
    (s = s.replace(/\([^()/]*\)/g, (group) => {
      // A capture inside a class too (`[(.*)]`, `[()]`): read as one, and
      // URLPattern rejects it
      if (/[$^]|^\(\?<?[=!]/.test(group.replace(/\[[^\]]*\]/g, "")) || group.includes("\0")) {
        invalidSyntax(
          "an anchor, look-around, backreference or capturing group in a constraint",
          route,
        );
      }
      if (classSetOp(group)) {
        invalidSyntax("a `--` / `&&` in a class of a constraint", route);
      }
      // Only a `(?:…)` may sit inside a constraint (a look-around threw above)
      return group[1] === "?" && group[2] !== "<" ? "" : "\0";
    }))
  );
  if (s.includes("(")) {
    throw new Error(
      `rou3: a \`(\` must close in its own segment, escape a literal one as \`\\(\` (${route})`,
    );
  }
  if (s.includes("\\")) {
    invalidSyntax("a `\\` must escape a char of its segment", route);
  }
  if (/[{}]/.test(s.replace(/\{[^{}]*\}/g, ""))) {
    invalidSyntax("unbalanced or nested `{}`", route);
  }
}

/**
 * Whether regex source `s` (escapes dropped, so `\-` / `\[` / `\]` are no
 * syntax) has a `--` / `&&` in a class: a set operation under URLPattern's
 * `v` flag (`[[a-z]--a]` is `b`-`z`), plain chars in rou3's RegExp. Classes
 * are read innermost-out, as the `v` flag nests them. Shared by
 * `checkConstraints` and `regExpToRoute`.
 */
export function classSetOp(s: string): boolean {
  let found = false;
  while (
    !found &&
    /--|&&/.test(s) &&
    s !==
      (s = s.replace(/\[[^[\]]*\]/g, (k) => {
        found ||= /--|&&/.test(k);
        return "_";
      }))
  );
  return found;
}

/**
 * Maps the index of an unnamed capture in a route to its key in a pattern: a
 * number, or the name of a `:name(.*)` (see `starGroups`).
 */
export type Unnamed = (index: number) => number | string;

/**
 * `path` (checked by `checkConstraints`) with every `(.*)` group written as
 * the `*` it is, as in URLPattern (the same token there): a greedy
 * catch-all, also inside a segment. A `:name(.*)` is that `*` keyed by
 * `name`, which may be `""`; returns the `unnamed` map that keys it (the
 * `*` takes an unnamed index in the rewritten route, the `(…)` groups before
 * it numbered as written). Where a `*` would read as a modifier or a `**`
 * (after a `:name`, a group or a `*`), or a group's `{` / `}` may put it
 * there, it is written after U+FFFF, which `joinGroup` drops where no such
 * thing is before it and `getParamRegexp` skips. A `(.*)*` stays, so its
 * modifier throws; a `(.*)?` / `(.*)+` is a `*?` / `*+`, which throw too.
 * Shared by `addRoute`, `removeRoute` and `routeToRegExp`.
 */
export function starGroups(path: string): [path: string, unnamed?: Unnamed] {
  if (!path.includes("(.*)")) return [path];
  // Unnamed groups so far (a `*` before a `:name(.*)` throws anyway). Only a
  // `(?:` nests (`checkConstraints`), so every other `(` is a capture.
  let count = 0;
  let unnamed: Unnamed | undefined;
  const out = path.replace(
    /\\[\s\S]|(:[A-Za-z_]\w*)?\((?!\?)(\.\*\)(?!\*))?/g,
    (m, name: string | undefined, star, at: number) => {
      // An escape, a constraint or another group
      if (m[0] === "\\" || !star) {
        if (m[0] === "(") count++;
        return m;
      }
      if (name) {
        const k = count;
        unnamed = (index) => (index === k ? name.slice(1) : index > k ? index - 1 : index);
      } else count++;
      return /(^|[^\\])(\\\\)*([)*}?]|:[A-Za-z_]\w*)\{?$/.test(path.slice(0, at)) ? "\uFFFF*" : "*";
    },
  );
  return [out, unnamed];
}

/**
 * A relative pattern (`foo/:id`) with a `/` in front, as `addRoute`,
 * `removeRoute` and `routeToRegExp` read it. A pattern starting with a `{`
 * group is left alone: `expandGroupDelimiters` reads each expansion of it
 * the same way (`{/:a}?/b` is absolute, as in URLPattern: `/:a/b` or `/b`,
 * not `//b`; the empty one of `{/:a}?` is `/`).
 */
export function absolutePattern(path: string): string {
  return /^[/{]/.test(path) ? path : `/${path}`;
}

/**
 * `path` with its `.` / `..` segments (`%2e` too, any case) resolved like
 * `new URL()` resolves a path, as URLPattern canonicalizes a pattern:
 * `/foo/../bar` is `/bar`, `/a/./b` is `/a/b`, a `..` at the root stays
 * there, and one ending the path leaves a `/` (`/a/b/..` is `/a/`). A segment
 * with an escape is text (`/\.\./bar`). URLPattern resolves each part of a
 * pattern on its own, so next to dynamic syntax its result is no path
 * (`/:id/..` is `/:id/`, `/a/../:id` is `//:id`, the `/` before a `:name`
 * being the param's): a `..` removing anything but plain text and a dot
 * segment right before a `:name` / `*` / `(…)` segment throw, and so does
 * one in a `{…}` group (`DOT_SEGMENT` in `expandGroupDelimiters`). Shared by
 * `addRoute`, `removeRoute` and `routeToRegExp`; after `checkConstraints`, so
 * every `/` splits segments (a group's `/` too: `/a{/b/../c}?` is
 * `/a{/c}?`, as in URLPattern).
 */
export function dotSegments(path: string): string {
  if (!DOT_SEGMENT.test(path)) return path;
  const s = path.split("/");
  const out = [s[0]];
  // The last segment was a dot segment
  let dot = false;
  for (let i = 1; i < s.length; i++) {
    const m = /^(?:\.|%2e)(\.|%2e)?$/i.exec(s[i]);
    if (m) {
      // A leading-group pattern's first piece is no root (`{a}/..`)
      if (m[1] && (out.length > 1 || out[0]) && !isText(out.pop()!)) {
        invalidSyntax(DOT_SEGMENT_NEXT_TO, path);
      }
      dot = true;
      continue;
    }
    if (dot && /^[:*(]/.test(s[i])) invalidSyntax(DOT_SEGMENT_NEXT_TO, path);
    out.push(s[i]);
    dot = false;
  }
  if (dot) out.push("");
  return out.join("/");
}

/** A segment of plain text: no param, catch-all, group or raw `?`. */
const isText = (segment: string) =>
  typeof segmentKey((segment = encodeEscapes(segment))) === "string" &&
  !/[{}]|(^|[^\\])\?/.test(segment);

/** A `.` / `..` segment (`%2e` too) somewhere in a pattern. */
export const DOT_SEGMENT: RegExp = /(?:^|\/)(?:\.|%2e){1,2}(?=\/|$)/i;

export const DOT_SEGMENT_NEXT_TO = "`.` / `..` segment next to a param, catch-all or group";

/**
 * Throws a `rou3:` error for pattern syntax with no meaning (yet), quoting the
 * route as written.
 */
export function invalidSyntax(what: string, route: string): never {
  throw new Error(`rou3: ${what} (${route})`);
}

/**
 * `?` / `+` / `*` anywhere but after a whole-segment `:name` (a `?` also after
 * `:name(…)` or in a mixed segment; none on a catch-all: `*`, `(.*)`, which
 * `starGroups` writes as a `*`, `**:name`), which covers a raw
 * `?` in plain text and a `**` in the middle of a segment too (one message,
 * bundle size; see docs/reference.md "Invalid patterns").
 */
export const MISPLACED_MODIFIER =
  "misplaced `?` / `+` / `*`: `?` follows `:name` or `:name(…)`, `+` / `*` a whole-segment `:name`, none a catch-all (`(.*)` too); escape a literal one with `\\`";

/**
 * A segment ending in a param's modifier: the text before the param, the
 * `:name` / `:name(…)`, the modifier.
 */
export const PARAM_MODIFIER: RegExp = /^(.*)(:[A-Za-z_]\w*(?:\([^)]*\))?)([?+*])$/;

/**
 * Expand the first `?` / `+` / `*` modifier of a param into the routes it
 * stands for. A `?` on a param that does not start its segment makes only the
 * param optional (`pre-:x?` is `pre-:x` or `pre-`, as in URLPattern;
 * `{pre-:x}?` drops the segment). After a capture (`*-:x?`, `:a(\\d+):b?`)
 * it stays for `getParamRegexp`, which compiles it in place: one regex, so a
 * greedy capture takes what it can first, as in URLPattern (the two routes
 * would let the one with the param win). `+` / `*` repeat a whole-segment
 * `:name` only: `input` (quoted in the error) repeating a constrained param
 * (`:x(\\d+)+`) or part of a segment (`pre-:x+`) throws: it would drop the
 * constraint / the rest of the segment.
 * A `?` on a `**:name` throws too (the `**` is no text before the param).
 */
export function expandModifiers(segments: string[], input?: string): string[] | undefined {
  for (let i = 0; i < segments.length; i++) {
    const last = segments[i].charCodeAt(segments[i].length - 1);
    if (last !== 63 /* ? */ && last !== 43 /* + */ && last !== 42 /* * */) continue;
    const m = segments[i].match(PARAM_MODIFIER);
    if (!m) continue;
    const pre = segments.slice(0, i);
    const suf = segments.slice(i + 1);
    // Without the param: the text before it in its segment, or no segment
    const without = "/" + pre.concat(m[1] || [], suf).join("/");
    // A `**` before it is no text: `**:name?` throws like `**:name+`
    if (m[3] === "?" && m[1] !== "**") {
      // After a capture, `getParamRegexp` compiles it in place (`*-:x?`)
      if (typeof segmentKey(m[1]) !== "string") continue;
      return ["/" + pre.concat(m[1] + m[2], suf).join("/"), without];
    }
    if (m[1] || m[2].includes("(")) {
      invalidSyntax(MISPLACED_MODIFIER, input!);
    }
    // `:name+` and `:name*` are `**:name` (a value, see `emptyParam`); `:name*`
    // also matches without the segment
    const wc = "/" + pre.concat("**" + m[2], suf).join("/");
    return m[3] === "+" ? [wc] : [wc, without];
  }
}

/**
 * A `*` inside a segment is a catch-all too, as in URLPattern (`/*.png` on
 * `/a/b.png` is `a/b`): the rest of its segment, any segments after it and
 * the start of a later one. The tree reads it as the segment-local `*`
 * (`[^/]*`, see `getParamRegexp`) before or after a `**` that `join`s their
 * captures (see `getMatchParams`): `pre*post` is `pre*`, `**`, `*post` (the
 * capture spans segments) and the segment as is (it doesn't), `*post` is
 * `**`, `*post`, and `pre*` is `pre*`, `**`. Returns those routes' segments,
 * the index of the `**` and whether a `pre*` segment is before it (its `*`
 * starts the capture), or `undefined` without such a `*`. Throws for a second
 * one (one catch-all per route).
 */
export function splitStar(
  segments: string[],
  input: string,
): [routes: string[][], join: number, head: boolean] | undefined {
  for (let i = 0; i < segments.length; i++) {
    const segment = segments[i];
    const at = segment.startsWith("**") || segment === "*" ? [] : segmentWildcards(segment);
    if (at.length === 0) continue;
    for (let j = i + 1; j < segments.length && at.length === 1; j++) {
      if (!segments[j].startsWith("**") && segments[j] !== "*") {
        at.push(...segmentWildcards(segments[j]));
      }
    }
    if (at.length > 1) {
      // A `**` inside a segment (`a**b`) has no meaning yet
      if (at.some((x, k) => at[k + 1] === x + 1)) invalidSyntax(MISPLACED_MODIFIER, input);
      oneCatchAll(input);
    }
    const pre = segments.slice(0, i);
    const post = segments.slice(i + 1);
    const head = segment.slice(0, at[0]);
    const tail = segment.slice(at[0] + 1);
    if (!head) return [[pre.concat("**", segment, post)], i, false];
    // `pre*` ending its segment: the segment as written (one segment, ranked
    // on its node like `pre*post`'s) and over more of them (a `**` that
    // needs a segment, see `_insert`)
    if (!tail) return [[pre.concat(segment, "**", post), segments], i + 1, true];
    return [[pre.concat(head + "*", "**", "*" + tail, post), segments], i + 1, true];
  }
}

/** Throws for a route with more than one catch-all, quoting it as written. */
export function oneCatchAll(input: string): never {
  throw new Error(
    `rou3: a route can have only one \`*\`, \`**\`, \`:name+\` or \`:name*\` (${input})`,
  );
}

/**
 * Like `splitPath`, for route patterns: `/a//` and `/a/` canonicalize to `/a`,
 * and a `**` followed by more of its segment reads like a `*` there, as in
 * URLPattern (`/**.md` is `/*.md`: any path ending in `.md`, one capture; a
 * third `*` is a second catch-all, `/***` is `/**\/*`). A `{` or `}` right
 * after the `**` is group syntax, not part of the segment (before group
 * expansion: `/a/**{.md}?` is `/a/**` or `/a/**.md`).
 */
export function splitRoute(path: string): string[] {
  const s = splitPath(path);
  while (s[s.length - 1] === "") s.pop();
  if (path.includes("**")) {
    for (let i = 0; i < s.length; i++) {
      if (/^\*\*[^:{}]/.test(s[i])) {
        s.splice(i, 1, ...(s[i][2] === "*" ? ["**", s[i].slice(2)] : [s[i].slice(1)]));
      }
    }
  }
  return s;
}

/**
 * Registration identity of a pattern that expands (groups, `?`/`+`/`*`
 * modifiers), shared by `addRoute` and `removeRoute`: its pre-expansion text
 * with trailing empties dropped and static segments keyed like the tree, so
 * spellings the tree cannot tell apart (`/a/:x?/` vs `/a/:x?`, `\)` vs `)`)
 * share one identity (compared through `routeId`). A pattern starting with a group (`{/:a}?/b`, the only
 * one here without a leading `/`) is read after a `/` (the split would drop
 * its first piece) and marked with a `{`, which no other identity starts
 * with: read after a `/`, `{a}?/b` would be the same text as `/{a}?/b`, and
 * both register `/a/b`.
 */
export function expandedRouteId(path: string): string {
  if (path.charCodeAt(0) !== 47 /* '/' */) return `{${expandedRouteId(`/${path}`)}`;
  return (
    "/" +
    splitRoute(encodeEscapes(path))
      .map((segment) => {
        const key = segmentKey(segment);
        return typeof key === "string" ? key : segment;
      })
      .join("/")
  );
}

/**
 * Record param `name` of an expansion of `input`, throwing on a repeat or on
 * a name that is not `[A-Za-z_]\w*` (`:0`, `:café`, `**:x(\\d+)`, `**:x.json`:
 * a `**:name` ends its segment). A `**:name` runs to its segment's end, so
 * the quoted name drops the `\` a group put before a name char outside a
 * constraint (`**:x{s}?` names `xs`) and decodes `encodeEscapes`' placeholders
 * (`**:x\:y` names `x\:y`).
 */
export function addName(names: string[], name: string, input: string): string {
  if (names.includes(name) || !/^[A-Za-z_]\w*$/.test(name)) {
    invalidSyntax(
      `${names.includes(name) ? "duplicate" : "invalid"} param name "${decodeEscapes(name.replace(/\\(?=[\w$\x80-\ufffc])(?![^(]*\))/g, ""), "\\")}"`,
      input,
    );
  }
  names.push(name);
  return name;
}

/**
 * Where the `*`s of a route segment are: unescaped, outside a `(...)` group
 * (escapes encoded, see `encodeEscapes`; a `\*` is a literal).
 */
function segmentWildcards(segment: string): number[] {
  const at: number[] = [];
  let depth = 0;
  for (let i = 0; i < segment.length; i++) {
    const ch = segment.charCodeAt(i);
    if (ch === 92 /* \\ */) {
      i++;
    } else if (ch === 40 /* ( */) {
      depth++;
    } else if (ch === 41 /* ) */ && depth > 0) {
      depth--;
    } else if (ch === 42 /* * */ && depth === 0) {
      at.push(i);
    }
  }
  return at;
}

import { toGroupName, toUnnamedGroupKey } from "./_group-names.ts";
import {
  addName,
  decodeEscapes,
  encodeLiteral,
  invalidSyntax,
  MISPLACED_MODIFIER,
  PARAM_MODIFIER,
} from "./_pattern.ts";

// The regex of a dynamic segment: as written (`getParamRegexp`, shared by
// `addRoute` and `routeToRegExp`) and the tree's linear-time form of it
// (`linearRegExp`).

/**
 * The regex of a dynamic segment (params, constraints, `*`), after its
 * modifier has been expanded and its escapes encoded (`encodeEscapes`); a `\x`
 * outside a group is a literal `x`. Throws on what has no meaning (yet) there:
 * a `:` without a valid name, an empty group or one starting with `?`, a `?` /
 * `+` / `*` modifier on anything but a whole segment's `:name` (a `?` / `+` would
 * be a raw regex quantifier, a `*` right after a name or group is ambiguous with
 * a modifier) and a mid-segment `**`. `routeToRegExp` reuses it (with its own
 * unnamed group keys), so a dynamic segment is the same regex in both.
 *
 * A `:name` here shares its segment, so it takes as little as possible
 * (`[^/]+?`, as in URLPattern: `:a-:b` on `x-y-z` is `x` and `y-z`); a `*`
 * stays greedy (URLPattern's `*` is a greedy `(.*)`). A `?` ending the
 * segment after a `:name` / `:name(…)` makes it optional in place
 * (`(?:(?<x>…))?`, unset when absent; `expandModifiers` leaves it here after
 * a capture), so the captures split the segment like URLPattern's regex. Its
 * name is the third element of the result.
 *
 * The fourth is the segment's rank among same-node siblings that tie on
 * weight (see `_selectMatcher`): 256 per literal char (as encoded), plus one
 * per constraint that can't match `""`, minus one per capture that can (a
 * `*`, an optional `:name?`, a constraint like `(\d*)`). Per capture, these
 * order what it takes: a constraint ⊆ a `:name` ⊆ a capture that may be `""`.
 */
export function getParamRegexp(
  segment: string,
  unnamedStart: number,
  names: string[],
  input: string,
  groupKey: (index: number) => string = toUnnamedGroupKey,
): [RegExp, number, string | undefined, number] {
  let _i = unnamedStart;
  // The in-place optional param's name
  let _o: string | undefined;
  // Replace \x escapes outside (...) with a \uFFFE placeholder
  let _s = "",
    _d = 0,
    // Index right after the last `:name`, top-level group or `*`
    _e = -1,
    // Where the top-level group starts, the rank (see above)
    _g = 0,
    _r = 0;
  // The constraints
  const _c: string[] = [];
  for (let j = 0; j < segment.length; j++) {
    const c = segment.charCodeAt(j);
    if (_d === 0) {
      // Before a `(.*)` group's `*` that follows a name, group or `*`: no
      // modifier, nor a name's constraint (see `starGroups`); dropped below
      if (c === 0xffff) {
        _s += "\uFFFF";
        continue;
      }
      if (c === 58 /* : */) {
        // A name is `[A-Za-z_]\w*` (a `-` ends it); a `$` or non-ASCII char
        // can't follow it (part of the name in URLPattern: `:id$` is `id$`)
        _e =
          j + 1 + addName(names, /^[\w$\x80-\ufffc]*/.exec(segment.slice(j + 1))![0], input).length;
      } else if (c === 40 /* ( */ && /[?)]/.test(segment[j + 1])) {
        invalidSyntax("empty or `(?` group", input);
      } else if (c === 63 /* ? */ || c === 43 /* + */ || (c === 42 /* * */ && j === _e)) {
        // A `?` ending the segment after a `:name` / `:name(…)` makes it
        // optional: kept raw for the name replace below (literal text is
        // percent-encoded, it would be `%3F`)
        if (c === 63 && j === segment.length - 1 && PARAM_MODIFIER.test(segment)) {
          _s += "?";
          _r--;
          continue;
        }
        // Otherwise `?` / `+` here would be raw quantifiers; a `*` right after
        // a name or group is ambiguous with a modifier, after a `*` a
        // mid-segment `**` (an escaped `\*` is consumed below and never sets
        // `_e`)
        invalidSyntax(MISPLACED_MODIFIER, input);
      } else if (c === 42) {
        // A `*` here is the part of a catch-all in this segment (see
        // `splitStar`), an unnamed group numbered with the others
        _e = j + 1;
        _s += "([^/]*)";
        _r--;
        continue;
      }
    } else if (c === 58) {
      // A `:` inside a group (`(?:`) is no param
      _s += "\uFFFE:";
      continue;
    }
    if (c === 40) {
      if (_d++ === 0) _g = j;
    } else if (c === 41 && _d > 0) {
      if (--_d === 0) {
        _e = j + 1;
        // A constraint (not `joinGroup`'s `:name`)
        const p = segment.slice(_g + 1, j);
        if (p !== "[^\\x2f]+?") _c.push(p);
      }
    } else if (_d === 0 && c === 0xfffd && /[34]/.test(segment[j + 1])) {
      // `encodeEscapes`' placeholders 3 and 4, an escaped `{` / `}`, are text;
      // the others (`\:` `\(` `\)` `\\`) stay hidden until params and groups
      // are named (`encodeLiteral` leaves U+FFFD alone)
      _s += encodeLiteral("{}"[+segment[++j] - 3]);
      _r += 768;
      continue;
    } else if (_d === 0 && /[\0- "#$).<>?[-^`{-}\x7F-\uFFFC]/.test(segment[j])) {
      // Outside a (...) group, a `\x` is a literal `x` (U+FFFE-marked; `\*`
      // stays an escape so it is no wildcard), and so are regex chars, as in
      // a static segment (`:x.json`, `*$`; inside a group they are regex:
      // `:id(\d+\.\d+)`). Literal text is percent-encoded like URLPattern
      // (`encodeLiteral`, a surrogate pair at once; `%XX` is no syntax).
      const esc = c === 92 && j + 1 < segment.length ? 1 : 0;
      const ch = segment.slice(j + esc, j + esc + (segment.codePointAt(j + esc)! > 0xffff ? 2 : 1));
      const encoded = encodeLiteral(ch);
      j += esc + ch.length - 1;
      _s += encoded !== ch ? encoded : esc && ch !== "*" ? "\uFFFE" + ch : "\\" + ch;
      _r += encoded.length * 256;
      continue;
    }
    // Text outside groups and names (an escape placeholder is one char)
    if (_d === 0 && j >= _e && segment.charCodeAt(j - 1) !== 0xfffd) _r += 256;
    _s += segment[j];
  }
  const regex = decodeEscapes(
    _s
      // Names were checked and recorded above; a `\uFFFE:` is inside a group.
      // `[^\x2f]+?` before a group is the `:name` `joinGroup` constrained,
      // emitted as `[^/]+?` (alone it stays as written).
      .replace(/(?<!\uFFFE):([A-Za-z_]\w*)(?:\(([^)]*)\))?(\?$)?/g, (m, id, p, o, i, s) => {
        const group = `(?<${toGroupName(id)}>${p && (p != "[^\\x2f]+?" || !/[(\uFFFF]/.test(s[i + m.length])) ? p : "[^/]+?"})`;
        return o ? ((_o = id), `(?:${group})?`) : group;
      })
      .replace(/\((?![?<])/g, () => `(?<${groupKey(_i++)}>`),
    "\uFFFE",
  ).replace(/\uFFFE([\s\S])|\uFFFF/g, (_, c = "") => (/[.*+?^${}()|[\]\\]/.test(c) ? `\\${c}` : c));

  const regexp = new RegExp(`^${regex}$`);
  for (const p of _c) {
    _r += new RegExp(`^(?:${decodeEscapes(p, "\\")})$`).test("") ? -1 : 1;
  }
  return [regexp, _i, _o, _r];
}

/**
 * The tree's form of a dynamic segment's regex (`getParamRegexp`): the same
 * matches and captures, without the polynomial backtracking of several
 * captures in one segment (`:year-:month-:day.html` on a long run of `-`
 * tried every split: cubic). Only rou3's own pieces are rewritten (`[^/]`
 * can't be in a constraint); a constraint stays as written.
 *
 * - A lazy `:name` (`[^/]+?`) followed by text `L` and then a `:name`, a `*`
 *   or a last `:name?` takes up to the first `L` (`[^/][^/L]*`, or a tempered
 *   `(?:(?!L)[^/])*` for longer text), and one followed by such a capture
 *   directly takes one char: the capture after it takes any value, so if a
 *   longer value let the rest match, the shortest does too (what `+?` picks).
 * - A `*` (`[^/]*`) followed only by text and such params ends where they
 *   start latest: matched once from the end of the segment in a look-behind
 *   (each param as short as it can be, the text before it the last one), as
 *   group 1, and the greedy `*` must leave exactly that (`(?=\1$)`; a longer
 *   rest is never tried, a shorter one fails `\1`'s length check at once).
 *
 * Each param then reads its text once, linear in the segment, but after a
 * constraint, which may still backtrack over what follows it. `routeToRegExp`
 * keeps `getParamRegexp`'s form (no look-around, any engine).
 */
export function linearRegExp(regexp: RegExp): RegExp {
  let source = regexp.source;
  // Only a lazy `:name` can take its text in more than one way
  if (!source.includes("[^/]+?)")) return regexp;
  let head = "";
  // `L`: a literal run (`\x` or a plain char); then `(?<n>[^/]+?)` or a last
  // `(?:(?<n>[^/]+?))?`
  source = source.replace(
    /(\(\?<\w+>\[\^\/\]\*\))((?:\\[\s\S]|[^\\()]|(?:\(\?:)?\(\?<\w+>\[\^\/\]\+\?\)(?:\)\?)?)*)\$$/,
    (all, star: string, rest: string) => {
      // Text alone after the `*` backtracks one char at a time already
      if (!rest.includes("+?")) return all;
      head = `(?=[^/]*$(?<=(${rest.replace(
        /((?:\\[\s\S]|[^\\()])+)(?=\()|(\(\?:)?\(\?<\w+>\[\^\/\]\+\?\)(?:\)\?)?/g,
        (_, L?: string, opt?: string) => (L ? L + upTo(L, true) : opt ? "" : "[^/]"),
      )})))`;
      return `${star}(?=\\1$)${rest}$`;
    },
  );
  source = source.replace(
    /\[\^\/\]\+\?\)((?:\\[\s\S]|[^\\()])*)(?=(?:\(\?:)?\(\?<\w+>\[\^\/\](?:\+\?|\*)\))/g,
    (_, L: string) => `[^/]${L && upTo(L)})${L}`,
  );
  return source === regexp.source ? regexp : new RegExp(`^${head}${source.slice(1)}`);
}

// A param's chars up to text `L` (`back`: in a look-behind)
const upTo = (L: string, back?: boolean) =>
  L.replace(/^\\/, "").length < 2 ? `[^/${L}]*` : back ? `(?:[^/](?<!${L}))*` : `(?:(?!${L})[^/])*`;

import { NullProtoObj } from "./object.ts";
import type { RouterContext } from "./types.ts";

/**
 * Create a new router. `T` is the type of the route data.
 */
export function createRouter<T = unknown>(): RouterContext<T> {
  const ctx: RouterContext<T> = {
    root: { key: "" },
    static: new NullProtoObj(),
  };
  return ctx;
}

import type { MethodData, Node } from "../types.ts";
import { methodEntries, reverseVariants } from "../_match.ts";

/**
 * Collect the routes of a wildcard's `suffix` trie that match `segments`,
 * least -> most specific (shallower suffixes first, then param, then static
 * children). The trie holds the segments after `**` last segment first, so it
 * is walked from the end of the path: `pos` is the next segment to match and
 * `start` the first one the `**` may take.
 *
 * Same-node siblings are ordered by weight (one point per passing regex, one
 * for a `**:name`, which must take a segment, plus `rank`, a tie-break), ties
 * with the method-agnostic (`""`) entries first, each in insertion order, or
 * reversed within each with `reverse` (findRoute takes the last match, and
 * ties go to the first-registered there; a route's own variants are always
 * so, see `reverseVariants`).
 */
export function collectSuffix<T>(
  node: Node<T>,
  method: string,
  segments: string[],
  start: number,
  pos: number,
  matches: MethodData<T>[],
  reverse?: boolean,
): void {
  const match = node.methods && methodEntries(node.methods, method, reverse);
  if (match) {
    const end = pos + 1;
    const weighted: [MethodData<T>, number][] = [];
    for (const m of reverse ? match : reverseVariants(match)) {
      const w = m.suffix![0];
      let weight = 0;
      for (const [index, , optional, empty] of m.paramsMap!) {
        if (index < 0 && !optional) {
          weight = end > start ? (empty ? 2 : 4) : -1;
        }
      }
      const regexps = m.paramsRegexp;
      for (let i = 0; i < regexps.length && weight >= 0; i++) {
        if (regexps[i]) {
          // A capture-only regex (`plain`: `:a:b?`) restricts no more than a
          // `:name`: it weighs a point only (no tie with one), less than a
          // `*` (`/*/:y` over `/**/:a:b?`)
          weight = regexps[i].test(segments[i > w ? i - w - 1 + end : i])
            ? weight + (m.paramsMap!.find((e) => e[0] === i)![3] ? 1 : 4)
            : -1;
        }
      }
      if (weight >= 0) {
        weighted.push([m, weight + m.rank]);
      }
    }
    for (const [m] of weighted.sort((a, b) => a[1] - b[1])) {
      matches.push(m);
    }
  }
  if (pos >= start) {
    if (node.param) {
      collectSuffix(node.param, method, segments, start, pos - 1, matches, reverse);
    }
    const staticChild = node.static?.[segments[pos]];
    if (staticChild) {
      collectSuffix(staticChild, method, segments, start, pos - 1, matches, reverse);
    }
  }
}

/**
 * Whether a route with segments after `**` matches `segments` (only subtrees
 * flagged `hasSuffix` are visited).
 */
export function hasSuffixMatch<T>(
  node: Node<T>,
  method: string,
  segments: string[],
  index: number,
): boolean {
  const trie = node.wildcard?.suffix;
  // Most paths miss on the last segment already
  if (trie && (trie.param || trie.static?.[segments[segments.length - 1]])) {
    const matches: MethodData<T>[] = [];
    collectSuffix(trie, method, segments, index, segments.length - 1, matches);
    if (matches.length > 0) {
      return true;
    }
  }
  if (index < segments.length) {
    const staticChild = node.static?.[segments[index]];
    if (staticChild?.hasSuffix && hasSuffixMatch(staticChild, method, segments, index + 1)) {
      return true;
    }
    if (node.param?.hasSuffix && hasSuffixMatch(node.param, method, segments, index + 1)) {
      return true;
    }
  }
  return false;
}

/**
 * Sort `matches` least -> most specific by comparing them from the last
 * segment of the path backwards: a literal segment beats a regex-constrained
 * param, which beats a plain param or a segment taken by `**`. Ties keep
 * their order (stable sort).
 *
 * Used instead of the tree order on paths a route with segments after `**`
 * matches: such a route is anchored at the end of the path, so the tree
 * order (which decides at the first segment) would let `/blog/**` or
 * `/blog/:slug` beat `/**\/_payload.json`, and a broader route beat a
 * narrower one (`/a/:p/**` over `/a/**\/x`).
 */
export function rankFromEnd<T>(matches: MethodData<T>[], segments: string[]): MethodData<T>[] {
  const n = segments.length;
  return matches.sort((a, b) => {
    for (let p = n - 1; p >= 0; p--) {
      const x = kindAt(a, n, p);
      const y = kindAt(b, n, p);
      if (x < 0 && y < 0) {
        // Both `**` cover `p` and every segment down to the later start:
        // equal, skip them (a comparison costs the segments around the `**`,
        // not the whole path).
        p = ~Math.min(x, y);
      } else if (Math.max(x, 0) !== Math.max(y, 0)) {
        return Math.max(x, 0) - Math.max(y, 0);
      }
    }
    return 0;
  });
}

/**
 * 3 literal, 2 regex param, 0 plain param (or a `plain` regex, which
 * restricts no more, `*:a`, `:a:b?`: else `/**\/:a:b?` would beat the
 * narrower `/b/:id`) at path
 * segment `p`, or where the `**` covers it (ranked as 0), `~start` of the
 * segments it takes.
 */
function kindAt(m: MethodData<unknown>, n: number, p: number): number {
  const suffix = m.suffix;
  const end = suffix ? n - suffix[1] : n;
  for (const [index, name, , plain] of m.paramsMap || []) {
    if (index < 0) {
      if (p >= ~index && p < end) {
        return index;
      }
    } else if ((suffix && index > suffix[0] ? index - suffix[0] - 1 + end : index) === p) {
      return typeof name === "string" || plain ? 0 : 2;
    }
  }
  return 3;
}

import { createRouter } from "./context.ts";
import { addRoute } from "./operations/add.ts";
import type { Node } from "./types.ts";

/**
 * The route-tree nodes a pattern lands on, each named by a pattern.
 *
 * Routes on the same node compete: for a given path, `findRoute` returns at most
 * one of them. `/users/:id` and `/users/:name` share a node, and so do
 * `/users/*` and `/users/**:rest`. Key per-route metadata by these keys instead
 * of the pattern text to group it per node.
 *
 * - `routeNodeKeys(a)` and `routeNodeKeys(b)` share a key if and only if `a`
 *   and `b` share a node.
 * - A param segment is keyed `:_0`, `:_1`, …, and a catch-all `**`.
 * - A pattern with optional syntax (`:x?`, `:x*`, `{...}?`) lands on several
 *   nodes, so the result is an array (deduplicated, outermost first).
 * - Each key is a valid pattern for its own node: `routeNodeKeys(key)` is
 *   `[key]`.
 * - Invalid patterns throw like `addRoute`.
 *
 * Sharing a node doesn't mean matching the same paths: keys drop regex
 * constraints, so `/u/:id(\d+)` and `/u/:slug([a-z]+)` share `/u/:_0` but never
 * match the same path. Use {@link compareRoutes} to compare matched paths.
 *
 * @example
 * routeNodeKeys("/users/:id"); // ["/users/:_0"]
 * routeNodeKeys("/users/:name"); // ["/users/:_0"] (same node)
 * routeNodeKeys("/admin/*"); // ["/admin/**"] (the node of `/admin/**`)
 * routeNodeKeys("/**:path/_payload.json"); // ["/**\/_payload.json"]
 * routeNodeKeys("/a/:x?"); // ["/a", "/a/:_0"]
 */
export function routeNodeKeys(pattern: string): string[] {
  let keys = _patternKeys.get(pattern);
  if (keys === undefined) {
    // Reuse the real insertion pipeline (group delimiters, escape encoding,
    // modifier expansion, segment classification) instead of re-parsing the
    // pattern: a second parser could drift from `addRoute` and would then
    // report node identities the router does not actually use — recreating the
    // very collision this function exists to expose.
    const ctx = createRouter();
    addRoute(ctx, "", pattern);
    keys = [];
    _collectKeys(ctx.root, "", keys);
    // Keep the memo bounded; pattern vocabularies are small in practice, so a
    // full reset on overflow is simpler than recency tracking.
    if (_patternKeys.size >= 1024) _patternKeys.clear();
    _patternKeys.set(pattern, keys);
  }
  // Callers must not be able to mutate the memoized array.
  return keys.slice();
}

// Pattern -> node keys memo for `routeNodeKeys` (see its doc comment).
const _patternKeys = new Map<string, string[]>();

function _collectKeys(node: Node, prefix: string, keys: string[]): void {
  // A node carries `methods` iff some route was registered on it, so walking
  // the throwaway tree yields one key per distinct node — deduplication is free.
  if (node.methods) _pushKey(keys, prefix || "/");
  if (node.static) {
    for (const key in node.static) {
      _collectKeys(node.static[key], prefix + "/" + _escapeKey(key), keys);
    }
  }
  if (node.param) _collectKeys(node.param, prefix + PARAM, keys);
  if (node.wildcard) _collectKeys(node.wildcard, prefix + "/**", keys);
  // A wildcard's suffix trie holds the segments after `**`, last one first
  if (node.suffix) _collectSuffixKeys(node.suffix, prefix, "", keys);
}

function _collectSuffixKeys(node: Node, prefix: string, suffix: string, keys: string[]): void {
  if (node.methods) _pushKey(keys, prefix + suffix);
  if (node.static) {
    for (const key in node.static) {
      _collectSuffixKeys(node.static[key], prefix, "/" + _escapeKey(key) + suffix, keys);
    }
  }
  if (node.param) _collectSuffixKeys(node.param, prefix, PARAM + suffix, keys);
}

// A param segment, named `:_0`, `:_1`, … once its key is complete (`addRoute`
// rejects a U+FFFF, so no static key holds one)
const PARAM = "/\uFFFF";

function _pushKey(keys: string[], key: string): void {
  let n = 0;
  keys.push(key.replace(/\uFFFF/g, () => `:_${n++}`));
}

/**
 * Encode a decoded static key back into route syntax, so it can never be
 * confused with the `:_N` / `**` node markers and re-registers as the same
 * static key: route-syntax punctuation and `\` are backslash-escaped (a static
 * `*` is `\*`).
 */
function _escapeKey(key: string): string {
  return key.replace(/[\\:(){}*]/g, "\\$&");
}
